SHA=lambda b:hashlib.sha256(b).hexdigest()
def source(p,ref=REF):
    b=subprocess.check_output(['git','show',ref+':'+p],cwd=ROOT)
    meta=subprocess.check_output(['git','log',ref,'-1','--format=%H|%cI','--',p],cwd=ROOT,text=True).strip().split('|')
    return b,dict(path=p,branchHead=ref,sha256=SHA(b),lastChangeCommit=meta[0],lastChangeDate=meta[1])
def save(name,obj):
    p=BASE/name
    if p.exists():raise RuntimeError('REFUSE_OVERWRITE:'+str(p))
    p.write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
